DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `account` varchar(50) NOT NULL COMMENT '账号',
  `password` varchar(255) NOT NULL,
  `username` varchar(50) NOT NULL COMMENT '用户名',
  `group_list` text COMMENT '绑定的群组列表，逗号分隔',
  `linked_account` varchar(100) DEFAULT NULL COMMENT '关联账号',
  `linked_password` varchar(255) DEFAULT NULL COMMENT '关联账号密码',
  `remark` varchar(255) DEFAULT NULL COMMENT 'å¤‡æ³¨ä¿¡æ¯',
  `role` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1-0-',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态：1-正常，0-禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26149 DEFAULT CHARSET=utf8mb4 COMMENT='用户表';
